def yrs(k): return f'{k[2]}–{k[3]}' if k[2]!=k[3] else f'{k[2]}'
def ktable(L,start=1):
    return table(['#','君王','年代（主前）','年数','评价','朝代/备注','同时期先知','经文','要点'],[[str(i+start),f'<b>{k[0]}</b>{k[1]}',yrs(k),('7日' if k[0]=='心利' else '6月' if k[0]=='撒迦利雅' else '1月' if k[0]=='沙龙' else '3月' if k[4]==0 else str(k[4])),VL[k[5]],k[6],E(k[7]) or '—',E(k[8]),rich(k[9])] for i,k in enumerate(L)])
def chart():
    W,H=1400,540; x0,x1=940,580
