    s=[f'<svg viewBox="0 0 {W} {H}" role="img" aria-label="分裂王国诸王年代图">']
    for y in range(940,579,10):
        big=y%50==0
        s.append(f'<line x1="{X(y):.1f}" y1="30" x2="{X(y):.1f}" y2="{H-20}" stroke="rgba(150,160,200,{0.35 if big else 0.12})" />')
        if big: s.append(f'<text x="{X(y):.1f}" y="22" font-size="13" text-anchor="middle" opacity=".8">{y}</text>')
    lanes=[('以色列（北国·撒玛利亚）',ISRAEL,150),('犹大（南国·耶路撒冷）',JUDAH,330)]
    for name,L,yb in lanes:
        s.append(f'<text x="44" y="{yb-108}" font-size="15" font-weight="800" fill="#f5c76b">{name}</text>')
        for i,k in enumerate(L):
            a,b=X(k[2]),X(k[3]); w=max(b-a,4); row=i%3; y=yb-row*16
            s.append(f'<rect x="{a:.1f}" y="{y}" width="{w:.1f}" height="12" rx="3" fill="{VC[k[5]]}" opacity=".9"><title>{k[0]} {yrs(k)} BC</title></rect>')
            s.append(f'<text transform="translate({a+2:.1f},{y-3}) rotate(-50)" font-size="11.5">{k[0]}</text>')
    # prophets
    P=[('以利亚',875,848),('以利沙',848,797),('约拿',785,760),('阿摩司',762,755),('何西阿',755,715),('以赛亚',740,681),('弥迦',735,700),('那鸿',660,650),('西番雅',635,625),('耶利米',627,580),('哈巴谷',609,605),('但以理',605,580),('以西结',593,580),('俄巴底亚',586,583)]
    yb=440; s.append(f'<text x="44" y="{yb-40}" font-size="15" font-weight="800" fill="#b18cff">先知</text>')
    for i,(n,a,b) in enumerate(P):
        y=yb+(i%3)*18-10; s.append(f'<rect x="{X(a):.1f}" y="{y}" width="{max(X(b)-X(a),4):.1f}" height="10" rx="3" fill="#b18cff" opacity=".85"/><text x="{X(a)+3:.1f}" y="{y-2}" font-size="11.5">{n}</text>')
    for j,(y,t,c) in enumerate([(931,'国分裂',"#f5c76b"),(853,'夸夸尔之战',"#5ec8ff"),(722,'北国亡于亚述',"#ff6b6b"),(701,'西拿基立围城',"#5ec8ff"),(622,'约西亚改革',"#3ee0a1"),(612,'尼尼微陷落',"#5ec8ff"),(605,'迦基米施·首次被掳',"#ff9f5a"),(597,'二次被掳',"#ff9f5a"),(586,'圣殿焚毁',"#ff6b6b")]):
        s.append(f'<line x1="{X(y):.1f}" y1="30" x2="{X(y):.1f}" y2="{H-20}" stroke="{c}" stroke-dasharray="4 4" stroke-width="1.6"/><text x="{X(y)+3:.1f}" y="{H-8-(j%2)*14}" font-size="12" fill="{c}">{y} {t}</text>' if y not in (605,597) else f'<line x1="{X(y):.1f}" y1="30" x2="{X(y):.1f}" y2="{H-20}" stroke="{c}" stroke-dasharray="2 4"/>')
    s.append('</svg>')
    return '<div class="chart reveal">'+''.join(s)+'</div><div class="legend"><span style="--c:#3ee0a1"><i></i>善王</span><span style="--c:#ff6b6b"><i></i>恶王</span><span style="--c:#ffb34d"><i></i>善恶参半</span><span style="--c:#b18cff"><i></i>先知事奉期</span><span>（手机可左右滑动；鼠标悬停看年代）</span></div>'
