PROPH=[('以利亚',875,848),('以利沙',848,797),('约珥',835,830),('约拿',785,760),('阿摩司',762,755),('何西阿',755,715),('以赛亚',740,681),('弥迦',735,700),('那鸿',660,650),('西番雅',635,625),('耶利米',627,580),('哈巴谷',609,605),('但以理',605,580),('以西结',593,580),('俄巴底亚',586,583)]
def kt():
    Y0,Y1=940,580; P=lambda y:(Y0-y)/(Y0-Y1)*100
    o=['<div class="track">']
    for y in range(Y0,Y1-1,-20):
        o.append(f'<div class="ax" style="left:{P(y):.2f}%">{y}</div>')
    lanes=[('🟥 以色列（北国）',ISRAEL,26),('🟦 犹大（南国）',JUDAH,128)]
    for nm,L,top in lanes:
        o.append(f'<div class="lane" style="top:{top}px;left:44px">{nm}</div>')
        for i,k in enumerate(L):
            a=P(k[2]); w=max(P(k[3])-a,.55); t=top+20+(i%3)*24
            info=f'<div class="co {"app" if k[5]=="good" else "hardc" if k[5]=="evil" else "trap"}"><span class="lb">{"🟥 北国" if L is ISRAEL else "🟦 南国"} · 第{i+1}位</span><p><b class="k">{E(k[0])}</b>{E(k[1])} · <span class="ub">{yrs(k)} BC</span> · {VTXT[k[5]]}{(" · "+E(k[6])) if k[6] else ""}</p><p>{E(k[9])}</p><p class="srcline">📖 {E(k[8])}{(" · 📯 先知："+E(k[7])) if k[7] else ""}</p></div>'
            o.append(f'<div class="kb {k[5]}" style="left:{a:.2f}%;width:{w:.2f}%;top:{t}px" data-html="{E(info)}" title="{E(k[0])} {yrs(k)}">{E(k[0])}</div>')
    o.append('<div class="lane" style="top:226px;left:44px;color:var(--vio)">📯 先知</div>')
    for i,(n,a,b) in enumerate(PROPH):
        info=f'<div class="co xc"><span class="lb">📯 先知</span><p><b class="k">{n}</b> · <span class="ub">约{a}–{b} BC</span></p></div>'
        o.append(f'<div class="kb pro" style="left:{P(a):.2f}%;width:{max(P(b)-P(a),.8):.2f}%;top:{246+(i%3)*18}px" data-html="{E(info)}">{n}</div>')
    for y,t,c in [(931,'国分裂','#ffcb5c'),(853,'夸夸尔','#5cc8ff'),(722,'北国亡','#ff6b6b'),(701,'西拿基立','#5cc8ff'),(622,'约西亚改革','#3ee0a1'),(586,'圣殿焚毁','#ff6b6b')]:
        o.append(f'<div class="evl" style="left:{P(y):.2f}%;--c:{c};top:304px">{y} {t}</div>')
    o.append('</div>')
    flt='<div class="filters" style="position:static;margin:6px 0">'+''.join(f'<button class="{"on" if v=="all" else ""}" data-kt="#kt1" data-kfilter="{v}">{t}</button>' for v,t in [('all','全部'),('good','✅ 善王'),('evil','❌ 恶王'),('mix','⚖️ 参半'),('pro','📯 先知')])+'<span class="srcline">点击色条查看详情 · 手机左右滑动</span></div>'
    return flt+'<div class="kt rv" id="kt1" data-info="#kinfo1">'+''.join(o)+'</div><div class="kinfo" id="kinfo1">'+co('info','<p>👆 点击（或悬停）任一君王/先知色条，在此显示：年代、评价、朝代、同时期先知、经文与要点。</p>','诸王详情')+'</div>'
ERAC={col:str(i) for i,(n,r,col,y) in enumerate(ERAS)}
def build():
    c=[]
    c.append(f'''<section class="hero reveal"><div class="chips"><span class="chip g">⏳ 时间线</span><span class="chip">保守派年代学（Thiele 式）</span><span class="chip">诸王全表</span></div>
<h1>从创造到新天新地：<em>一条时间线记住整本圣经</em></h1><p class="lead">先用 <b>11 个时代</b>搭骨架，再用 <b>8 个“钉子年份”</b>钉住，最后把 <b>3 位统一王国君王 + 19 位以色列王 + 20 位犹大君王</b>与 <b>先知、帝国</b>挂上去。年份为主前（BC）除非注明；共治期使不同王的年代重叠，属正常现象。</p></section>''')
    c.append(legend_box())
    c.append('<div class="eraband" aria-hidden="true">'+''.join(f'<span style="--c:{col}" title="{n}"></span>' for n,r,col,y in ERAS)+'</div>')
    c.append(h2('ov','🧱','总览：骨架 · 钉子 · 主线'))
    c.append(h3('eras','十一个时代：整本圣经的骨架'))
    c.append('<div class="era reveal">'+''.join(f'<a href="#master" style="--c:{col}"><b>{n}</b>{y}<br><small>{r}</small></a>' for n,r,col,y in ERAS)+'</div>')
    c.append(mer('''flowchart LR
A["🌍 创造·堕落<br/>创1–11"]-->B["⛺ 族长<br/>~2166–1805"]-->C["🔥 出埃及<br/>1446"]-->D["🗡️ 征服·士师<br/>1406–1050"]-->E["👑 统一王国<br/>1050–931"]-->F["💔 分裂王国<br/>931–586"]-->G["⛓️ 被掳<br/>605–538"]-->H["🏗️ 归回<br/>538–430"]-->I["🤫 两约之间<br/>430–5"]-->J["✝️ 基督<br/>5 BC–AD 30"]-->K["🕊️ 教会<br/>AD 30–"]
style C fill:#5a2440,stroke:#ff7aa8
style E fill:#173a5a,stroke:#5ec8ff
style J fill:#5a4614,stroke:#f5c76b''','救赎历史的十一站（流程图）'))
    c.append(h3('pegs','八个“钉子年份”：先背这 8 个'))
    pegs=[('2091','亚伯兰蒙召入迦南','#ff9f5a'),('1446','出埃及','#ff7aa8'),('1010','大卫登基','#5ec8ff'),('966','建殿（前推480年=1446）','#5ec8ff'),('931','国分裂','#8ea2ff'),('722','北国亡（亚述）','#ff6b6b'),('586','南国亡（巴比伦）','#ff6b6b'),('538','归回（波斯古列）','#34d6d0')]
    c.append('<div class="steps reveal">'+''.join(f'<div style="--c:{col}"><span class="e">📍</span><b>{y}</b><span>{t}</span></div>' for y,t,col in pegs)+'</div>')
    c.append(note('🧠 记忆口诀','<p><span class="mn">“一四四六出埃及，九六六年把殿立；九三一年国分裂，七二二北、五八六南；五三八年回故里”</span></p><p>验算：966 + 480 = 1446（王上6:1）；1446 − 430 = 1876 雅各下埃及（出12:40）；586 − 516 ≈ 70 年（圣殿荒凉七十年）；605 − 536/538 ≈ 70 年（耶25:11）。</p>','gold'))
    c.append(h3('master','主时间线：从亚伯拉罕到拔摩岛'))
    c.append('<div class="tl">'+''.join(f'<div class="ev reveal" data-era="{ERAC.get(col,"")}" style="--c:{col}"><span class="d">{rich(d)}</span>{rich(t,False)}<br><small style="color:var(--mut)">{r}</small></div>' for d,t,col,r in EVENTS)+'</div>')
    c.append(h2('kingdom','👑','王国时代：统一 · 分裂 · 先知'))
    c.append(h3('united','统一王国（约1050–931）：三王各四十年'))
    c.append(ktable(UNITED))
    c.append(note('🧠 口诀','<span class="mn">“扫大所，各四十；扫罗失心，大卫得约，所罗门建殿后失足”</span>（徒13:21；王上2:11；11:42）','emer'))
    c.append(h3('divided','分裂王国（931–586）：交互式诸王时间轴'))
    c.append(kt())
    c.append(h4('divided-svg','静态总图（打印/截图用）'))
